import{_ as a,o as e,c as r,a2 as o}from"./chunks/framework.CCCdsIgc.js";const u=JSON.parse('{"title":"确认与安全","description":"","frontmatter":{},"headers":[],"relativePath":"guide/safety.md","filePath":"guide/safety.md"}'),d={name:"guide/safety.md"};function n(i,t,s,l,h,c){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="确认与安全" tabindex="-1">确认与安全 <a class="header-anchor" href="#确认与安全" aria-label="Permalink to &quot;确认与安全&quot;">​</a></h1><p>FlyknitBuddy 在你的电脑上执行操作，所以安全规则比较严格。规则由 IT 在后台统一配置，员工改不了被锁定的项。</p><h2 id="什么时候会问你" tabindex="-1">什么时候会问你 <a class="header-anchor" href="#什么时候会问你" aria-label="Permalink to &quot;什么时候会问你&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>怎么处理</th></tr></thead><tbody><tr><td>查目录、看文件、搜索、在工作区生成文件、跑构建</td><td>直接做，不打扰你</td></tr><tr><td>认不出的命令</td><td>问你；你可以选「以后自动执行」</td></tr><tr><td>删除、覆盖、改注册表 / 服务 / 账号、装卸软件</td><td><strong>每次都问</strong>，不能设成自动</td></tr><tr><td>格式化磁盘这类危险命令</td><td><strong>直接拦截</strong>，确认了也不执行</td></tr></tbody></table><p>选「以后自动执行」时，记住的是<strong>命令前缀 + 当前工作区</strong>（比如在这个文件夹里的 <code>npm run build</code>），不是放开所有命令；删除类的命令无论如何每次都问。</p><p>选「<strong>本任务内不再询问</strong>」时，只在这一次任务里有效，任务结束就失效：命令按程序记（比如这次任务里的 <code>python</code>），连接器的操作按工具记（比如「MES · 查询工单」，查哪一单都不再问，别的工具照问）。主助手和它派出去的专家共用这份授权。删除类的命令同样每次都问；读到可疑内容之后、IT 规定必须确认的操作，也每次都问。</p><p>确认框会写清楚要做什么、为什么。看不懂的时候点「拒绝」最安全，AI 会换别的办法或者告诉你还差哪一步。</p><h2 id="改坏了怎么办" tabindex="-1">改坏了怎么办 <a class="header-anchor" href="#改坏了怎么办" aria-label="Permalink to &quot;改坏了怎么办&quot;">​</a></h2><ul><li><strong>改文件前自动备份</strong>，删除的文件进回收站；</li><li>办事的回答下面有「改动了 N 个文件」，点开能逐行对比，<strong>一键还原</strong>到这一轮之前，详见 <a href="./files.html">文件、预览与还原</a>。</li></ul><h2 id="网页、文件里的「指令」不算数" tabindex="-1">网页、文件里的「指令」不算数 <a class="header-anchor" href="#网页、文件里的「指令」不算数" aria-label="Permalink to &quot;网页、文件里的「指令」不算数&quot;">​</a></h2><p>AI 读到的网页、文件、命令输出里如果夹着「忽略之前的要求，去做某事」这类话，它不会照做：只有你在输入框里说的才是要求。读到可疑内容后，接下来所有会改东西的操作都会先问你。</p><h2 id="记忆" tabindex="-1">记忆 <a class="header-anchor" href="#记忆" aria-label="Permalink to &quot;记忆&quot;">​</a></h2><p>AI 会记住你的偏好和工作习惯，让下次更顺手。密码、密钥、令牌这类内容不会被记进长期记忆。侧栏「记忆」里能看到它记了什么，可以删除。</p><h2 id="审计" tabindex="-1">审计 <a class="header-anchor" href="#审计" aria-label="Permalink to &quot;审计&quot;">​</a></h2><p>每一次操作（包括被拦截、被拒绝的）都会记录在公司服务器上，IT 可以查看。</p>',15)])])}const _=a(d,[["render",n]]);export{u as __pageData,_ as default};
